/* Helper for AF */
RV_STATIC_INLINE void funPinAF(u32 pin, u32 af)
{
	volatile uint32_t* afio = (uint32_t*)(AFIO_BASE + 4U + 4U * (pin >> 3));
	*afio = (*afio & ~(0xf << (4U * (pin & 0x7)))) | (af << (4U * (pin & 0x7)));
